script:
(function () {
  'use strict';
  // Health FSA tax savings. Your election comes out of pay before tax, so it saves:
  //   federal + state income tax = election x (federal rate + state rate)
  //   Social Security            = 6.2% x (wages under the wage base before - after the election)
  //   Medicare                   = 1.45% x election
  // Use-it-or-lose-it: leftover = election - min(election, expected expenses); with a carryover
  // plan up to the 2026 maximum rolls into next year, the rest is forfeited (with a grace period,
  // expenses up to 2.5 months after the plan year are counted in "expected expenses").
  // Net benefit = total tax saved - amount forfeited.
  // CHECKS (Node, scratch tests): $60,000 salary, $2,500 election, 22% + 5%: income tax $675,
  // SS $155, Medicare $36.25, total $866.25; expenses $1,800 -> leftover $700, forfeited $700
  // (no carryover) -> net $166.25, or $20 forfeited with carryover ($680 carried); salary
  // $186,000, election $3,400 -> SS saved only on $1,900 below the $184,500 base ($117.80);
  // salary $250,000 -> SS saved $0; election above $3,400 is capped at $3,400.
  // ---- 2026 LIMITS --------------------------------------------------------------------------
  // Health FSA: IRS Rev. Proc. 2025-32, section 3.15 (IRC 125(i)) - salary reduction limit
  // $3,400 and maximum carryover of unused amounts $680, for plan years beginning in 2026.
  // FICA: 6.2% Social Security + 1.45% Medicare employee rates (IRC 3101); 2026 Social Security
  // wage base $184,500 (SSA 2026 COLA fact sheet).
  var FSA = { year: 2026, salaryReductionLimit: 3400, carryoverMax: 680 };
  var FICA = { ss: 0.062, medicare: 0.0145, ssWageBase: 184500 };
  // --------------------------------------------------------------------------------------------

  // p: salary, election, expenses, fed, state (decimals), rule ('none' | 'carryover' | 'grace')
  function fsaSavings(p) {
    var election = Math.max(0, Math.min(p.election, FSA.salaryReductionLimit, p.salary));
    var fedTax = election * p.fed, stateTax = election * p.state;
    var ss = FICA.ss * (Math.min(p.salary, FICA.ssWageBase) - Math.min(p.salary - election, FICA.ssWageBase));
    var medicare = FICA.medicare * election;
    var total = fedTax + stateTax + ss + medicare;
    var used = Math.min(election, p.expenses), left = election - used;
    var carried = p.rule === 'carryover' ? Math.min(left, FSA.carryoverMax) : 0;
    var forfeited = left - carried;
    return { election: election, capped: p.election > FSA.salaryReductionLimit, fedTax: fedTax, stateTax: stateTax,
             ss: ss, medicare: medicare, total: total, used: used, carried: carried, forfeited: forfeited,
             net: total - forfeited, rate: election > 0 ? total / election : p.fed + p.state + FICA.ss + FICA.medicare };
  }

  var moneyFmt = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  function money(x) { return moneyFmt.format(Math.abs(x) < 0.5 ? 0 : x); }
  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { document.getElementById(id).textContent = text; }

  function update() {
    var salary = num('fsSalary'), election = num('fsElection'), expenses = num('fsExpenses'),
        fed = parseFloat(document.getElementById('fsFed').value), state = num('fsState'),
        rule = document.getElementById('fsRule').value;
    var error = document.getElementById('fsError');
    var msg = '';
    if ([salary, election, expenses, fed, state].some(isNaN) || salary < 0 || election < 0 || expenses < 0)
      msg = 'Enter non-negative amounts in every field.';
    else if (state > 15) msg = 'Enter a state tax rate from 0 to 15%.';
    else if (election > salary) msg = 'Your FSA election cannot be more than your salary.';
    error.hidden = !msg;
    if (msg) { error.textContent = msg; return; }
    var base = { salary: salary, expenses: expenses, fed: fed / 100, state: state / 100, rule: rule };
    function run(e) { base.election = e; return fsaSavings(base); }
    var r = run(election);
    set('fsTotal', money(r.total));
    set('fsNet', money(r.net));
    set('fsForfeit', money(r.forfeited));
    set('fsCarried', money(r.carried));
    set('fsFedTax', money(r.fedTax));
    set('fsStateTax', money(r.stateTax));
    set('fsSs', money(r.ss));
    set('fsMed', money(r.medicare));
    set('fsPer100', money(100 * (1 - r.rate)));
    var capEl = document.getElementById('fsCapped');
    capEl.hidden = !r.capped;
    if (r.capped) capEl.textContent = 'The ' + FSA.year + ' limit is ' + money(FSA.salaryReductionLimit) +
        ' per employee, so the results use ' + money(FSA.salaryReductionLimit) + '. If you are married, your spouse can elect up to the same amount through their own employer.';
    var riskEl = document.getElementById('fsRisk');
    var best = Math.min(expenses, FSA.salaryReductionLimit, salary);
    riskEl.hidden = !(r.forfeited > 0.5);
    if (r.forfeited > 0.5) {
      var b = run(best);
      riskEl.textContent = 'Use it or lose it: ' + money(r.forfeited) + ' of your election would not be spent' +
          (r.carried > 0.5 ? ' even after carrying ' + money(r.carried) + ' into next year' : '') +
          ' and would be forfeited, wiping out that much of your tax savings. Electing ' + money(best) +
          ' instead would save ' + money(b.total) + ' with nothing lost.';
    }
    var levels = [];
    for (var e = 500; e < FSA.salaryReductionLimit; e += 500) levels.push(e);
    levels.push(FSA.salaryReductionLimit);
    var mine = Math.min(election, FSA.salaryReductionLimit);
    if (levels.indexOf(mine) < 0) levels.push(mine);
    levels = levels.filter(function (x) { return x <= salary; });
    levels.sort(function (a, b) { return a - b; });
    var body = document.getElementById('fsTable');
    body.textContent = '';
    levels.forEach(function (lv) {
      var x = run(lv), tr = document.createElement('tr');
      [money(lv) + (lv === mine ? ' (yours)' : ''), money(x.total), money(x.carried), money(x.forfeited), money(x.net)]
        .forEach(function (v) { var td = document.createElement('td'); td.textContent = v; tr.appendChild(td); });
      body.appendChild(tr);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    set('fsLimit', money(FSA.salaryReductionLimit));
    set('fsCarryMax', money(FSA.carryoverMax));
    var form = document.getElementById('fsForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
